mapper.insert:
insert into biz_consumable(
	consumable_code, consumable_name, spec, unit, stock_qty, warn_qty, create_by, create_time, remark
)values(
	#{consumableCode}, #{consumableName}, #{spec}, #{unit}, #{stockQty}, #{warnQty}, #{createBy}, sysdate(), #{remark}
)

mapper.update:
update biz_consumable
consumable_code = #{consumableCode}, consumable_name = #{consumableName}, spec = #{spec}, unit = #{unit}, warn_qty = #{warnQty}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where consumable_id = #{consumableId}

mapper.insert:
insert into biz_consumable_record(
	consumable_id, record_type, quantity, before_qty, after_qty, content, operator, create_time
)values(
	#{consumableId}, #{recordType}, #{quantity}, #{beforeQty}, #{afterQty}, #{content}, #{operator}, sysdate()
)

mapper.select:
select r.record_id, r.consumable_id, r.record_type, r.quantity, r.before_qty, r.after_qty, r.content, r.operator, r.create_time,
       c.consumable_code, c.consumable_name
from biz_consumable_record r
	left join biz_consumable c on c.consumable_id = r.consumable_id


		AND r.consumable_id = #{consumableId}


		AND r.record_type = #{recordType}


		AND r.create_time >= #{params.beginCreateTime}


		AND r.create_time <= #{params.endCreateTime}


order by r.create_time desc, r.record_id desc
